const root = $json || {};
const nested = (root.body && typeof root.body === 'object' && !Array.isArray(root.body)) ? root.body : {};
let skus = nested.skus || root.skus || nested.sku || root.sku || [];

if (typeof skus === 'string') {
  skus = skus.split(/[\n,;]+/).map(s => s.trim()).filter(Boolean);
}
if (!Array.isArray(skus)) {
  skus = [skus];
}

skus = skus.map(s => String(s).trim().replace(/'/g, '')).filter(Boolean);

if (skus.length === 0) {
  return [{
    json: {
      skus: [],
      skusInClause: "''",
      client_id: nested.client_id || root.client_id || '',
      oi: nested.oi || root.oi || ''
    }
  }];
}

const skusInClause = skus.map(s => `'${s}'`).join(', ');

return [{
  json: {
    skus: skus,
    skusInClause: skusInClause,
    client_id: nested.client_id || root.client_id || '',
    platform: nested.platform || root.platform || '',
    oi: nested.oi || root.oi || ''
  }
}];

const inputSkus = $('Preparar SKUs').first().json.skus || [];
const rows = $input.all().map(item => item.json);

const sku_map = {};
for (const s of inputSkus) {
  sku_map[s] = { cat: [], trad: [], product_id: '', sku_id: '' };
}

for (const row of rows) {
  if (!row || !row.sku) continue;
  const sku = String(row.sku || '').trim();
  const mlb = String(row.mlb || '').trim().toUpperCase();
  const isCat = Number(row.is_catalog || 0);
  const status = String(row.status_in_marketplace || 'active');
  const productId = String(row.product_id || row.productId || '').trim();
  const skuId = String(row.sku_id || row.skuId || '').trim();

  if (!sku_map[sku]) {
    sku_map[sku] = { cat: [], trad: [], product_id: '', sku_id: '' };
  }
  if (productId && !sku_map[sku].product_id) {
    sku_map[sku].product_id = productId;
  }
  if (skuId && !sku_map[sku].sku_id) {
    sku_map[sku].sku_id = skuId;
  }
  const marketplaceId = String(row.marketplace_id || row.marketplaceId || '').trim();
  if (sku && mlb && mlb.startsWith('MLB')) {
    const slot = { mlb, status, marketplace_id: marketplaceId };
    if (isCat === 1) {
      sku_map[sku].cat.push(slot);
    }
    else {
      sku_map[sku].trad.push(slot);
    }
  }
}

return [{
  json: {
    success: true,
    sku_map: sku_map,
    count: Object.keys(sku_map).length
  }
}];
